// app/core/schema.sql + app/modules/*/schema.sql 을 Supabase 마이그레이션 한 파일로 모은다.
// 생성물(supabase/migrations/20261103000000_tenant_tables.sql)은 손으로 고치지 않는다.
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const OUT_REL = 'supabase/migrations/20261103000000_tenant_tables.sql';

const HEADER = [
  '-- GENERATED by scripts/build-migration.mjs from app/core/schema.sql and app/modules/*/schema.sql.',
  '-- Do not edit by hand: change the schema files and run `npm run build:migration`.',
  '-- Tenant tables (every row carries workspace_id). RLS, FKs and grants: 20261103000001_saas_platform.sql.',
].join('\n');

/** @param {string} sql @returns {string[]} 테이블 이름 (등장 순) */
export function listTables(sql) {
  return [...sql.matchAll(/CREATE TABLE IF NOT EXISTS\s+([a-z_][a-z0-9_]*)/gi)].map((m) => m[1]);
}

/**
 * @param {{ root: string }} opts
 * @returns {string}
 */
export function buildMigration({ root }) {
  const files = ['app/core/schema.sql'];
  const modulesDir = path.join(root, 'app/modules');
  if (existsSync(modulesDir)) {
    const ids = readdirSync(modulesDir)
      .filter((n) => statSync(path.join(modulesDir, n)).isDirectory())
      .sort();
    for (const id of ids) {
      const rel = `app/modules/${id}/schema.sql`;
      if (existsSync(path.join(root, rel))) files.push(rel);
    }
  }
  const parts = files.map((rel) => {
    const body = readFileSync(path.join(root, rel), 'utf8').replace(/\r\n/g, '\n').trim();
    return `-- source: ${rel}\n${body}`;
  });
  return `${HEADER}\n\n${parts.join('\n\n')}\n`;
}

function main(argv) {
  const out = buildMigration({ root: ROOT });
  const outPath = path.join(ROOT, OUT_REL);
  if (argv.includes('--check')) {
    const current = existsSync(outPath) ? readFileSync(outPath, 'utf8') : null;
    if (current === out) {
      console.log('migration up to date');
      return 0;
    }
    console.log('migration stale: run npm run build:migration');
    return 1;
  }
  writeFileSync(outPath, out);
  console.log(`built ${OUT_REL} (${listTables(out).length} tables)`);
  return 0;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  process.exitCode = main(process.argv.slice(2));
}
